import {escapeHTML as esc,money,icon,productGrid,ProductImage} from './components.js';
const labels={optical:'Оправы для зрения',sunglasses:'Солнцезащитные очки',women:'Женские',men:'Мужские',unisex:'Унисекс'};
function breadcrumb(items) {
  return `<nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a>${items.map(item => `<span aria-hidden="true">/</span>${item.href ? `<a href="${esc(item.href)}">${esc(item.label)}</a>` : `<span aria-current="page">${esc(item.label)}</span>`}`).join('')}</nav>`;
}
export function productDetailHTML(product,related,mockNotice=''){
 const photo=product.images[0];
 return `<section class="product-page wrap">${breadcrumb([{label:'Каталог',href:'/catalog'},{label:labels[product.category],href:'/catalog/'+product.category},{label:product.brand+' '+product.model}])}<div class="product-detail"><div class="product-gallery"><div class="gallery-main" id="gallery-main">${ProductImage(photo,{id:'gallery-image',loading:'eager'})}<button class="favorite-button icon-button" data-favorite="${esc(product.id)}" aria-label="В избранное: ${esc(product.brand)} ${esc(product.model)}" aria-pressed="false">${icon('heart')}</button></div><div class="gallery-thumbs" aria-label="Виды модели">${product.images.map((image,index) => `<button class="gallery-thumb ${index === 0 ? 'selected' : ''}" data-gallery-src="${esc(image.src)}" data-gallery-alt="${esc(image.alt)}" aria-label="${index === 0 ? 'Общий вид' : 'Фото '+(index+1)}" aria-pressed="${index === 0}">${ProductImage(image,{loading:'eager'})}<span>${index === 0 ? 'Общий вид' : 'Фото '+(index+1)}</span></button>`).join('')}<button class="gallery-thumb detail-thumb" data-gallery-detail aria-label="Детали оправы" aria-pressed="false">${ProductImage(photo,{loading:'eager'})}<span>Детали</span></button></div>${product.isMock ? '<p class="prototype-note">Иллюстрация концепции, не фотография реальной модели бренда.</p>' : ''}</div><div class="product-detail-info"><p class="eyebrow">${esc(product.brand)}</p><h1>${esc(product.model)}</h1><p class="detail-price">${money(product.price)}${product.oldPrice ? `<s>${money(product.oldPrice)}</s>` : ''}</p><p class="product-type">${labels[product.category]} · ${labels[product.gender]}</p><p class="detail-description">${esc(product.shortDescription)}<br>${esc(product.description)}</p><dl class="attributes">${Object.entries(product.attributes).map(([label,value]) => `<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="product-detail-actions"><button class="button" data-request-product="${esc(product.id)}">Уточнить наличие / примерить в салоне</button></div>${product.isMock ? mockNotice : ''}<div class="product-accordions"><details><summary>Примерка в салоне</summary><p>Покупка доступна в салоне. Уточните наличие понравившейся модели перед визитом.</p></details><details><summary>Подбор и консультация</summary><p>Поможем сравнить посадку и форму, обсудить подходящие линзы. Индивидуальный подход — без навязывания лишних услуг.</p><button class="text-button" data-booking>Записаться на проверку зрения</button></details></div></div></div><section class="related-section"><div class="collection-heading"><h2>Вам может понравиться</h2><a class="text-button" href="/catalog/${product.category}">Все модели</a></div>${productGrid(related)}</section></section>`;
}
